class Solution:
    def anagramTwins(self, s: str) -> int:
        n, total = len(s), 0
        for L in range(1, n):
            sigs = ["".join(sorted(s[i:i + L])) for i in range(n - L + 1)]
            for i in range(len(sigs)):
                for j in range(i + 1, len(sigs)):
                    if sigs[i] == sigs[j]:
                        total += 1
        return total

