class Solution {
    public int anagramTwins(String s) {
        int n = s.length(), total = 0;
        for (int L = 1; L < n; L++) {
            String[] sigs = new String[n - L + 1];
            for (int i = 0; i + L <= n; i++) {
                char[] c = s.substring(i, i + L).toCharArray();
                Arrays.sort(c);
                sigs[i] = new String(c);
            }
            for (int i = 0; i < sigs.length; i++)
                for (int j = i + 1; j < sigs.length; j++)
                    if (sigs[i].equals(sigs[j])) total++;
        }
        return total;
    }
}

