    for (int L = 1; L < n; L++) {
        int m = n - L + 1;
        for (int i = 0; i < m; i++) {
            memset(cnt[i], 0, sizeof cnt[i]);
            for (int k = i; k < i + L; k++) cnt[i][s[k] - 'a']++;
        }
        for (int i = 0; i < m; i++)
            for (int j = i + 1; j < m; j++)
                if (memcmp(cnt[i], cnt[j], sizeof cnt[i]) == 0) total++;
    }
    free(cnt);
    return total;
}

