from collections import Counter

class Solution:
    def anagramTwins(self, s: str) -> int:
        n, total = len(s), 0
        codes = [ord(c) - 97 for c in s]
        for L in range(1, n):
            cnt = [0] * 26
            for c in codes[:L]:
                cnt[c] += 1
            seen = Counter([tuple(cnt)])
            for i in range(L, n):
                cnt[codes[i]] += 1
                cnt[codes[i - L]] -= 1
                seen[tuple(cnt)] += 1
            total += sum(k * (k - 1) // 2 for k in seen.values())
        return total

