class Solution {
    public int anagramTwins(String s) {
        int n = s.length(), total = 0;
        for (int L = 1; L < n; L++) {
            int[] cnt = new int[26];
            for (int i = 0; i < L; i++) cnt[s.charAt(i) - 'a']++;
            Map<String, Integer> seen = new HashMap<>();
            seen.merge(Arrays.toString(cnt), 1, Integer::sum);
            for (int i = L; i < n; i++) {
                cnt[s.charAt(i) - 'a']++;
                cnt[s.charAt(i - L) - 'a']--;
                seen.merge(Arrays.toString(cnt), 1, Integer::sum);
            }
            for (int k : seen.values()) total += k * (k - 1) / 2;
        }
        return total;
    }
}

