static int by_counts(const void* x, const void* y) { return memcmp(x, y, 26 * sizeof(int)); }

int anagramTwins(char* s) {
    int n = strlen(s), total = 0;
    int (*sig)[26] = malloc((n + 1) * sizeof *sig);
    for (int L = 1; L < n; L++) {
        int cnt[26] = {0}, m = 0;
        for (int i = 0; i < L; i++) cnt[s[i] - 'a']++;
        memcpy(sig[m++], cnt, sizeof cnt);
        for (int i = L; i < n; i++) {
            cnt[s[i] - 'a']++;
            cnt[s[i - L] - 'a']--;
            memcpy(sig[m++], cnt, sizeof cnt);
        }
        qsort(sig, m, sizeof *sig, by_counts);
        for (int i = 0, j; i < m; i = j) {
            for (j = i; j < m && memcmp(sig[i], sig[j], sizeof cnt) == 0; j++);
            total += (j - i) * (j - i - 1) / 2;
        }
    }
    free(sig);
    return total;
}
